from typing import TypeVar, Generic, Callable

T = TypeVar('T')

class Trackable:
    def __init__(self, track: Callable[[T], None]):
        self.track = track

    def __call__(self, person: T) -> None:
        self.track(person)

class TrackableAssistant(Trackable, Generic[T]):
    def __init__(self, track: Callable[[T], None]):
        super().__init__(track)

    def __call__(self, person: T) -> None:
        self.track(person)

# Usage
class Student(Trackable):
    def __init__(self, name: str):
        self.name = name

    def __call__(self, person: str) -> None:
        print(f"Hello, {person}! Nice to meet you.")

assistant = TrackableAssistant(Student)
assistant('Alice')
```

